            { "BoardingDifficultyMultiplier", ("Difficulté d'abordage", "Nombre de marins ennemis à vaincre pour gagner un abordage (1 = normal).") },
            { "Coop.SharedQuests", ("Quêtes partagées", "Une quête coop terminée par un joueur se valide pour les autres qui l'ont active.") },
            { "Coop.StatsCorrectionModifier", ("Adaptation ennemis (joueurs)", "Ajuste la vie et la perte de posture des ennemis selon le nombre de joueurs.") },
            { "Coop.ShipStatsCorrectionModifier", ("Adaptation navires (joueurs)", "Ajuste la vie des navires ennemis selon le nombre de joueurs.") },
            { "EasyExplore", ("Exploration immersive", "ACTIVÉ masque les marqueurs de points d'intérêt (exploration plus difficile). Attention : le nom est inversé — « vrai » rend l'exploration plus dure.") },
        };

        private static Dictionary<string, (string label, string desc)> Map(string game)
        {
            if (string.IsNullOrEmpty(game)) { return null; }
            if (game.StartsWith("Palworld", StringComparison.OrdinalIgnoreCase)) { return Palworld; }
            if (game.StartsWith("7 Days to Die", StringComparison.OrdinalIgnoreCase)) { return SevenDaysToDie; }
            if (game.StartsWith("Project Zomboid", StringComparison.OrdinalIgnoreCase)) { return ProjectZomboid; }
            if (game.StartsWith("Windrose", StringComparison.OrdinalIgnoreCase)) { return Windrose; }
            return null;
        }

        public static string Group(string game, string group)
        {
            if (!Fr || string.IsNullOrEmpty(group)) { return group; }
            return Groups.TryGetValue(group, out var g) ? g : group;
        }

        public static string Label(string game, FieldSpec spec)
        {
            if (Fr) { var m = Map(game); if (m != null && m.TryGetValue(spec.Key, out var t) && !string.IsNullOrEmpty(t.label)) { return t.label; } }
            return spec.Label;
        }

        public static string Desc(string game, FieldSpec spec)
        {
            if (Fr) { var m = Map(game); if (m != null && m.TryGetValue(spec.Key, out var t)) { return t.desc; } }
            return spec.Description;
        }
    }
}
